    @EventHandler( payloadType=CreateDataSourceEvent.class )
    public void handle( CreateDataSourceEvent event) {
	    LOGGER.info("handling CreateDataSourceEvent - " + event );
	    DataSource entity = new DataSource();
            entity.setDataSourceId( event.getDataSourceId() );
            entity.setName( event.getName() );
            entity.setConnection( event.getConnection() );
            entity.setStreaming( event.getStreaming() );
            entity.setSourceType( event.getSourceType() );
            entity.setFormat( event.getFormat() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllDataSource( entity );
    }

