    /**
     * Method to retrieve the DataSource via an DataSourcePrimaryKey.
     * @param 	id Long
     * @return 	DataSource
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public DataSource handle( FindDataSourceQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getDataSourceId() );
    }
    
    /**
     * Method to retrieve a collection of all DataSources
     *
     * @param	query	FindAllDataSourceQuery 
     * @return 	List<DataSource> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<DataSource> handle( FindAllDataSourceQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindDataSource,
 * but only if the id matches
 *
 * @param		entity	DataSource
 */
	protected void emitFindDataSource( DataSource entity ) {
		LOGGER.info("handling emitFindDataSource" );
		
	    queryUpdateEmitter.emit(FindDataSourceQuery.class,
	                            query -> query.getFilter().getDataSourceId().equals(entity.getDataSourceId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllDataSource
	 * 
	 * @param		entity	DataSource
	 */
	protected void emitFindAllDataSource( DataSource entity ) {
		LOGGER.info("handling emitFindAllDataSource" );
		
	    queryUpdateEmitter.emit(FindAllDataSourceQuery.class,
	                            query -> true,
	                            entity);
	}

